/* U+00B7 is a two-byte UTF-8 symbol in valid CP949 (A1A4). The bundled
 * fonts already contain the centered araea dot at image 11264. Reuse that
 * drawing only: keep A1A4/U+00B7 distinct from A4FD/U+318D in stored text,
 * and leave the original 11266-entry table and every atlas index unchanged. */
static const korean_entry middle_dot = {0xa1a4, {0xc2, 0xb7, 0}, 11264};

static korean_entry *utf8_to_codepage;

/* Multilingual letters the CP949 table lacks (Cyrillic, Latin-1 ...) use its user-defined area:
 * slot k <-> 0xC9A1 + k (k < 94) or 0xFEA1 + k - 94. The glyphs come with the Noto font (image_has_korean_extra). */
int encoding_korean_extra_index(uint16_t code)
{
    int k = code >= 0xc9a1 && code <= 0xc9fe ? code - 0xc9a1 : code >= 0xfea1 && code <= 0xfefe ? 94 + code - 0xfea1 : -1;
    return k >= 0 && k < KOREAN_EXTRA_CHARS ? k : -1;
}

static int extra_code_for(unsigned codepoint)
{
    for (int k = 0; k < KOREAN_EXTRA_CHARS; k++) {
        if (korean_extra_chars[k] == codepoint) return k < 94 ? 0xc9a1 + k : 0xfea1 + k - 94;
    }
    return 0;
}

static int compare_utf8(const void *a, const void *b)
{
    const uint8_t *va = ((const korean_entry*) a)->utf8;
    const uint8_t *vb = ((const korean_entry*) b)->utf8;
    for (int i = 0; i < 3; i++) {
        if (va[i] == vb[i]) {
            continue;
        }
        return va[i] < vb[i] ? -1 : 1;
    }
    return 0;
}

static int compare_codepage(const void *a, const void *b)
{
    uint16_t va = ((const korean_entry*) a)->cp949;
    uint16_t vb = ((const korean_entry*) b)->cp949;
    return va == vb ? 0 : (va < vb ? -1 : 1);
}

void encoding_korean_init(void)
{
    if (!utf8_to_codepage) {
        utf8_to_codepage = (korean_entry*) malloc(sizeof(korean_entry) * IMAGE_FONT_MULTIBYTE_KOREAN_MAX_CHARS);
        if (!utf8_to_codepage) {
            log_error("Unable to allocate memory for Korean codepage", 0, 0);
            return;
        }
    }
    // codepage_to_unicode is already sorted, copy data and sort the other way around
    memcpy(utf8_to_codepage, codepage_to_utf8,
        IMAGE_FONT_MULTIBYTE_KOREAN_MAX_CHARS * sizeof(korean_entry));

    qsort(utf8_to_codepage, IMAGE_FONT_MULTIBYTE_KOREAN_MAX_CHARS, sizeof(korean_entry), compare_utf8);
}

void encoding_korean_to_utf8(const uint8_t *input, char *output, int output_length)
{
    if (output_length <= 0) return;
    const char *max_output = &output[output_length - 1];

    while (*input && output < max_output) {
        if (*input < 0x80) {
            *output = *input;
            ++output;
            ++input;
        } else {
            // multi-byte char
            if (!input[1]) break;
            int extra = encoding_korean_extra_index((uint16_t) (input[0] << 8 | input[1]));
            if (extra >= 0) {
                unsigned c = korean_extra_chars[extra];
                int bytes = c < 0x800 ? 2 : 3;
                if (max_output - output < bytes) break;
                if (bytes == 2) {
                    *output++ = (char) (0xc0 | (c >> 6));
                } else {
                    *output++ = (char) (0xe0 | (c >> 12));
                    *output++ = (char) (0x80 | ((c >> 6) & 0x3f));
                }
                *output++ = (char) (0x80 | (c & 0x3f));
                input += 2;
                continue;
            }
            const korean_entry key = {input[0] << 8 | input[1]};
            const korean_entry *entry = key.cp949 == middle_dot.cp949 ? &middle_dot :
                bsearch(&key, codepage_to_utf8, IMAGE_FONT_MULTIBYTE_KOREAN_MAX_CHARS,
                    sizeof(korean_entry), compare_codepage);
            if (entry) {
                int bytes = entry == &middle_dot ? 2 : 3;
                if (max_output - output < bytes) break;
                for (int i = 0; i < bytes; i++) {
                    *output = entry->utf8[i];
                    output++;
                }
            }
            input += 2;
        }
    }
    *output = 0;
}

void encoding_korean_from_utf8(const char *input, uint8_t *output, int output_length)
{
    if (output_length <= 0) return;
    if (!utf8_to_codepage) {
        output[0] = 0;
        return;
    }
    const uint8_t *max_output = &output[output_length - 1];

    while (*input && output < max_output) {
        if ((*input & 0x80) == 0) {
            *output = *input;
            ++output;
            ++input;
        } else {
            // The centered-dot symbol is two UTF-8 bytes; Korean letters are three.
            if ((uint8_t)input[0] == middle_dot.utf8[0] && (uint8_t)input[1] == middle_dot.utf8[1]) {
                if (max_output - output < 2) break;
                *output++ = (middle_dot.cp949 >> 8) & 0xff;
                *output++ = middle_dot.cp949 & 0xff;
                input += 2;
                continue;
            }
            int bytes = encoding_get_utf8_character_bytes((uint8_t)*input);
            int available = 1;
            while (available < bytes && input[available]) ++available;
            if (bytes == 2 && available == 2 && ((uint8_t)input[1] & 0xc0) == 0x80) {
                int code = extra_code_for((((uint8_t) input[0] & 0x1f) << 6) | ((uint8_t) input[1] & 0x3f));
                if (code && max_output - output < 2) break;
                if (code) { *output++ = code >> 8; *output++ = code & 0xff; }
                else *output++ = '?';
                input += 2;
                continue;
            }
            if (bytes != 3 || available != 3 ||
                ((uint8_t)input[1] & 0xc0) != 0x80 || ((uint8_t)input[2] & 0xc0) != 0x80) {
                *output++ = '?';
                input += available;
                continue;
            }
            const korean_entry key = {0, {(uint8_t)input[0], (uint8_t)input[1], (uint8_t)input[2]}};
            const korean_entry *entry = bsearch(&key, utf8_to_codepage,
                IMAGE_FONT_MULTIBYTE_KOREAN_MAX_CHARS, sizeof(korean_entry), compare_utf8);
            if (entry) {
                // A short destination must keep a complete prefix, not create '?'.
                if (max_output - output < 2) break;
                *output = (entry->cp949 >> 8) & 0xff;
                output++;
                *output = entry->cp949 & 0xff;
                output++;
                input += 3;
            } else {
                int code = extra_code_for((((uint8_t) input[0] & 0x0f) << 12) | (((uint8_t) input[1] & 0x3f) << 6) |
                    ((uint8_t) input[2] & 0x3f));
                if (code && max_output - output < 2) break;
                if (code) { *output++ = code >> 8; *output++ = code & 0xff; }
                else *output++ = '?';
                input += 3;
            }
        }
    }
    *output = 0;
}

int encoding_korean_image_id(uint16_t code)
{
    if (code == middle_dot.cp949) return middle_dot.image_id;
    const korean_entry key = {code};
    const korean_entry *entry = bsearch(&key, codepage_to_utf8,
        IMAGE_FONT_MULTIBYTE_KOREAN_MAX_CHARS, sizeof(korean_entry), compare_codepage);
    return entry ? entry->image_id : -1;
}
